  skylight: { x0: 6, x1: 9, z0: 15, z1: 17, y: 17 },
  deck: {
    x0: 1, x1: 14, z0: 31, z1: 35, y: 4,
    posts: [[1, 31], [14, 31], [1, 35], [7, 35], [14, 35]], postY: 3,
