  porch: { x0: 10, x1: 14, z0: 7, z1: 9, floorY: 4, voidY0: 5, voidY1: 8, ceilingY: 9, columnXs: [10, 14], columnZ: 7, wainscotXs: [9, 15], wainscotZs: [8, 9] },
