  drive: { x0: 3, x1: 6, z0: 0, z1: 3 },
  plinth: { x0: 1, x1: 8, y0: 0, y1: 3, z0: 4, z1: 6, stringY: 3 },
  garageDoor: { x0: 3, x1: 6, y0: 1, y1: 3, z: 4 },
  bay: {
    y0: 4, y1: 16,
