  entry: { x0: 11, x1: 12, y: 5, z: 10, transomY: 8, casingXs: [10, 13] },
  stoop: { x0: 11, x1: 13, treads: [[1, 2], [2, 3], [3, 4], [4, 5]], landing: { y: 4, z: 6 }, cheekXs: [10, 14], cheekZ0: 2, cheekZ1: 6, cheekTops: [1, 2, 3, 4, 4] },
